//! Reference output of HotSpot 25 (`ImageIO` JPEG writer over libjpeg 6b) for
//! the deterministic images of `tools/probes/Sbr5JpegOracle.java`. Generated.

pub struct Case {
    pub gray: bool,
    pub w: usize,
    pub h: usize,
    pub quality: f32,
    /// CRC32 of the `getRGB` ARGB bytes `ImageIO.read` returns for `jpeg`.
    pub dec_crc: u32,
    pub jpeg_hex: &'static str,
}

